// app/lib/ui-i18n.ts GENERATED by cache/scratch/gen_ui_i18n.py.
//
// Shared chrome that is not a LangBlocks pair: an aria-label has to be a plain
// string, and SearchModal builds its input attributes directly, so there was no
// <En>/<Ja> sibling for the per-block flag invariant to key off. The search
// placeholder, the keyboard hints and three aria-labels therefore stayed English
// on every ja/zh/ko page - and SearchModal is mounted on the destinations pages.
//
// Keyed by the English string, which stays the source of truth.
//
// Non-ASCII is written as \\uXXXX escapes - escapes cannot be mangled by the write path.

export type UiLang = "ja" | "zh" | "ko";

